--
-- Name: _add_luck_boost(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._add_luck_boost(p_user_id uuid, p_amount integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_amount IS NULL OR p_amount < 1 OR p_amount > 20 THEN
    RAISE EXCEPTION 'luck boost out of range: %', p_amount;
  END IF;

  UPDATE public.profiles
  SET active_luck_boost = LEAST(50, COALESCE(active_luck_boost, 0) + p_amount)
  WHERE id = p_user_id;
END;
$$;


