    CONSTRAINT profiles_aura_check CHECK ((aura >= 0)),
    CONSTRAINT profiles_role_allowed CHECK ((role = ANY (ARRAY['user'::text, 'admin'::text]))),
    CONSTRAINT profiles_theme_check CHECK ((theme = ANY (ARRAY['classic'::text, 'modern'::text])))
);


--
-- Name: leaderboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.leaderboard WITH (security_invoker='false') AS
 SELECT id,
    username,
    aura,
    xp,
    level,
    streak_days,
    created_at
   FROM public.profiles
  ORDER BY xp DESC;


