CREATE TABLE public.parties (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    emblem text DEFAULT '⚔'::text,
    leader_id uuid NOT NULL,
    max_members integer DEFAULT 6 NOT NULL,
    aura_pool integer DEFAULT 0 NOT NULL,
    xp_pool integer DEFAULT 0 NOT NULL,
    is_recruiting boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT parties_aura_pool_check CHECK ((aura_pool >= 0)),
    CONSTRAINT parties_max_members_check CHECK (((max_members >= 2) AND (max_members <= 8))),
    CONSTRAINT parties_xp_pool_check CHECK ((xp_pool >= 0))
);


