-- Name: party_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.party_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    party_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text DEFAULT 'member'::text NOT NULL,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT party_members_role_check CHECK ((role = ANY (ARRAY['leader'::text, 'officer'::text, 'member'::text])))
);


--
-- Name: party_directory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.party_directory WITH (security_invoker='false') AS
 SELECT p.id,
    p.name,
    p.description,
    p.emblem,
    p.leader_id,
    l.username AS leader_username,
    p.max_members,
    p.aura_pool,
    p.xp_pool,
    p.is_recruiting,
    p.created_at,
    (( SELECT count(*) AS count
           FROM public.party_members m
          WHERE (m.party_id = p.id)))::integer AS member_count
   FROM (public.parties p
     JOIN public.profiles l ON ((l.id = p.leader_id)));


